#!/usr/bin/env node
// `pnpm abi`: builds the contracts and writes their ABIs to packages/shared/src/abi/*.ts as `as const`
// exports for viem. The generated files are committed so the apps work without a Foundry install.
import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "contracts/out");
const DEST = join(ROOT, "packages/shared/src/abi");

// [source file, contract name, export name]
const CONTRACTS = [
  ["AgentVault.sol", "AgentVault", "agentVaultAbi"],
  ["VaultFactory.sol", "VaultFactory", "vaultFactoryAbi"],
  ["MockERC20.sol", "MockERC20", "mockErc20Abi"],
  ["MockOracle.sol", "MockOracle", "mockOracleAbi"],
  ["MockRouter.sol", "MockRouter", "mockRouterAbi"],
];

const build = spawnSync("forge", ["build"], { cwd: join(ROOT, "contracts"), stdio: "inherit" });
if (build.status !== 0) process.exit(build.status ?? 1);

mkdirSync(DEST, { recursive: true });
const header = "// Generated by `pnpm abi` from contracts/out. Do not edit.\n";
for (const [file, contract, name] of CONTRACTS) {
  const { abi } = JSON.parse(readFileSync(join(OUT, file, `${contract}.json`), "utf8"));
  writeFileSync(
    join(DEST, `${name}.ts`),
    `${header}export const ${name} = ${JSON.stringify(abi, null, 2)} as const;\n`,
  );
}
const index = CONTRACTS.map(([, , name]) => `export { ${name} } from "./${name}.ts";`).join("\n");
writeFileSync(join(DEST, "index.ts"), `${header}${index}\n`);

spawnSync(process.execPath, [join(ROOT, "node_modules/prettier/bin/prettier.cjs"), "--write", DEST], {
  stdio: "ignore",
});
console.log(`[abi] wrote ${CONTRACTS.length} ABIs to packages/shared/src/abi`);
